local MColor = require("Module:MColor");
local p = {}
local author = {}
local mt = {}
mt.__index = function (t,key)
local v = author[key];
if v then
return type(v) == "string"
and function() return v end
or v;
end
return function ()
return "Author Not Found!!!"
end
end
setmetatable(p,mt);
local function getRandomC(length,str)
local t = {}
for i = 1, length do
t[i] = string.char(string.byte(str,math.random(#str)));
end
return table.concat(t);
end
local function getRandom(length)
local str = "qertupoasdkhnbcvzx" -- 用于随机的字符
local t = {}
for i = 1, 100 do
local s = "<span class='nhRandomCharacter' style='animation-delay:"
.. tostring(-i/100) .. "s;'>" .. getRandomC(length,str) .. "</span>";
t[i] = s;
end
return table.concat(t)
end
local function wrap(str,style)
style = style or "";
return '<span class="nhAuthor" style="' .. style .. '">' .. str .. "</span>";
end
function author.Cloud()
local t = {}
local str = getRandom(1)
t[1] = '<span class="nhAuthorCloud" style="animation-delay:-3s">' .. MColor._3b(str) .. '</span>'
t[2] = '<span class="nhAuthorCloud" style="animation-delay:-2.5s">' .. MColor._3b('⎋') .. '</span>'
