t[4] = '<span class="nhAuthorCloud" style="animation-delay:-1.5s">' .. MColor._3b('ஃ') .. '</span>'
t[5] = '<span class="nhAuthorCloud" style="animation-delay:-1s">' .. MColor._3b(str) .. '</span>'
t[6] = '<span class="nhAuthorCloud" style="animation-delay:-0.5s">' .. MColor._3b('⦼') .. '</span>'
