color = "#5470C6"
}
}
}
}
local chart = frame:callParserFunction('#echarts', {"option="..mw.text.jsonEncode(option), "style=height:300px"})
response = {
chart = chart
}
-- return chart
local html = {'<div class="lua-smart-response">'}
for k, v in pairs(response) do
local valueStr = v
-- if type(v) == "table" then
-- -- 如果是 table（比如 echarts 的 option），转成 JSON 字符串
-- valueStr = mw.text.jsonEncode(v)
-- else
-- valueStr = tostring(v)
-- end
-- 使用 mw.text.nowiki 或适当转义防止 HTML 注入
table.insert(html, string.format(
'<div class="form-response" data-variable="%s">%s</div>',
k, valueStr
))
end
table.insert(html, '</div>')
return table.concat(html)
end
return p
