local p={}
local function sep(s)local n='';if s:sub(1,1)=='-'then n='-';s=s:sub(2)end;while true do local a,b=s:gsub('^(%d+)(%d%d%d)','%1,%2');s=a;if b==0 then break end end;return n..s end
local function f2(v)local n=tonumber(v)or 0;local r=math.floor(n*100+0.5)/100;local i,f=string.format('%.2f',r):match('^([%-]?%d+)%.(%d%d)$');return sep(i)..'.'..f end
local function fi(v)return sep(tostring(math.floor((tonumber(v)or 0)+0.5)))end
local function fEu(v)local n=tonumber(v)or 0;if n>=1e12 then return string.format('%.2fT',n/1e12)elseif n>=1e9 then return string.format('%.2fB',n/1e9)elseif n>=1e6 then return string.format('%.2fM',n/1e6)elseif n>=1e3 then return string.format('%.1fK',n/1e3)else return fi(n)end end
local function fLps(v)local n=tonumber(v)or 0;if n<=0 then return'---'end;if n>=1e6 then return string.format('%.2fM',n/1e6)elseif n>=1e3 then return string.format('%.1fk',n/1e3)else return f2(n)end end
local function getTier(s)if s>5.12e9 then return 5 elseif s>6.4e8 then return 4 elseif s>3.2e8 then return 3 elseif s>1.6e8 then return 2 else return 1 end end
local function maxOC(mt,rt)return math.max(0,mt-rt)end
local function calcRate(a,d,oc,ocf)local eff=d/(ocf^oc);local dd=math.max(math.floor(eff),1);local sm=1;if eff<1 then local no=math.ceil(math.log(d)/math.log(ocf));local eo=math.max(oc-no,0);local em=ocf^eo;local co=(ocf^no)/d;sm=math.ceil(em*co)end;return a*sm/dd end
local function cmpPar(mt,rt)return 64*(1+math.max(0,mt-rt))end
local gfRecipes={
['铁等离子体']={a=144,d=20,m=false,t=0},
['钙等离子体']={a=144,d=20,m=false,t=0},
['镅等离子体']={a=144,d=20,m=false,t=0},
['钛等离子体']={a=144,d=20,m=false,t=0},
['氧等离子体']={a=500,d=120,m=true,t=0},
['氡等离子体']={a=500,d=40,m=false,t=0}
}
local function gfRecipe(n)return gfRecipes[n]end
local function gfRate(n,fuel)
fuel=fuel or 25;if fuel<1 then fuel=1 end
local rec=gfRecipe(n);if not rec then return 0,0,0,0,0,0,0 end
local effectiveFuel=fuel<=43 and fuel or 43+math.floor((fuel-43)^0.4)
local h=12601+math.floor(math.log(fuel)/math.log(1.5)*1000)
local speedBonus=h^(-0.01);local ocf=4-25000/h
local fuelMultiplier=1+effectiveFuel/15
local heatMultiplier=1+h/25000
local upgradeMultiplier=1+14/8
local maxP=math.floor(512*2*fuelMultiplier*2*heatMultiplier*upgradeMultiplier)
local energyDiscount=1-(1-1.05^(-0.05*9223372036854775807))/20
local recE=503316480
local processingVoltage=(2000000000+effectiveFuel*100000000)*16
local oc=0;while recE*(4^(oc+1))<=processingVoltage do oc=oc+1 end
local effectiveDuration=math.max(1,math.floor(rec.d*speedBonus/(ocf^oc)+0.5))
local ratePerPar=rec.a/(effectiveDuration/20)
local powerPerPar=recE*(4^oc)*energyDiscount
return ratePerPar*maxP,powerPerPar*maxP,maxP,ratePerPar,powerPerPar,oc,effectiveDuration
end
