(function () {
var memCache = Object.create(null);
function cacheKey($n) {
return $n.attr('data-cache-key') || '';
}
function getLS(k) {
if (!k) return null;
try {
var raw = localStorage.getItem('tt:' + k);
if (!raw) return null;
var obj = JSON.parse(raw);
return obj && obj.html ? obj.html : null;
} catch (e) {
return null;
}
}
function setLS(k, html) {
if (!k || !html) return;
try {
localStorage.setItem('tt:' + k, JSON.stringify({ html: html, ts: Date.now() }));
} catch (e) {}
}
function buildUrl($n) {
var p = new URLSearchParams();
p.set('name', $n.attr('data-name') || '');
p.set('key', $n.attr('data-key') || '');
p.set('nbt', $n.attr('data-nbt') || '');
p.set('lang', $n.attr('data-lang') || 'zh');
return '/wiki/模板:ItemTooltipAsyncEndpoint?' + p.toString();
}
function renderOne($n) {
var k = cacheKey($n);
if (k && memCache[k]) {
$n.html(memCache[k]).removeClass('huiji-tt-preload');
return;
}
var hit = getLS(k);
if (hit) {
memCache[k] = hit;
$n.html(hit).removeClass('huiji-tt-preload');
return;
}
fetch(buildUrl($n), { credentials: 'same-origin' })
.then(function (r) { return r.text(); })
.then(function (html) {
// 视 endpoint 输出格式决定是否取 body 子节点；这里假定直接可嵌入
if (k) memCache[k] = html;
setLS(k, html);
$n.html(html).removeClass('huiji-tt-preload');
mw.hook('wikipage.content').fire($n);
});
}
mw.hook('wikipage.content').add(function ($content) {
$content.find('.async-minecraft-tt').not('.is-loaded').each(function () {
var $n = $(this);
$n.addClass('is-loaded');
renderOne($n);
});
});
})();
