if(time <= 1) then return 0.0375;end
local time2 = time/2.0 + time/2.0*0.0289 + time/2.0*0.0087*2;
return time2;
end
local function calcOutputTimePerHour(time)
return 60*60*20.0/calcOutputTime(time);
end
