local p = {}
function p.renderChart(frame)
-- 获取传入参数
local args = frame.args
local x1 = tonumber(args[1]) or 0
local x2 = tonumber(args[2]) or 40
local isLogType = (args['isLogType'] and args['isLogType'] ~= "") and "log" or "value"
-- 生成数据点函数
local function generateData(formulaType)
local points = {}
-- 步长根据范围自动调整，保证曲线平滑
local step = (x2 - x1) / 100
for x = x1, x2, step do
local y = 0
if formulaType == 'f' then
y = 300 * math.pow(1.15, x)
elseif formulaType == 'g' then
y = 2 * math.pow(1.08, x)
elseif formulaType == 'h' then
y = x / 25
end
-- 处理数值：如果不是对数坐标且数值过大，ECharts 渲染可能会有压力
table.insert(points, {x, tonumber(string.format("%.4f", y))})
end
return points
end
-- 构造 ECharts Option
local option = {
title = {
text = "函数增长对比图",
left = "center",
top = 0
},
tooltip = {
trigger = "axis",
axisPointer = { type = "cross" }
},
legend = {
top = "8%",
data = {"f(x)", "g(x)", "h(x)"}
},
grid = {
top = "15%", -- 进一步压缩顶部间距
left = "5%",
right = "8%",
bottom = "5%",
containLabel = true
},
xAxis = {
type = "value",
name = "x",
min = x1,
max = x2
},
yAxis = {
type = isLogType, -- 动态切换坐标轴类型
name = "y (Scale: " .. isLogType .. ")",
splitLine = { show = true }
},
series = {
{
name = "f(x)",
type = "line",
showSymbol = false,
smooth = true,
data = generateData('f')
},
{
name = "g(x)",
type = "line",
showSymbol = false,
smooth = true,
data = generateData('g')
},
{
name = "h(x)",
type = "line",
showSymbol = false,
smooth = true,
data = generateData('h')
}
}
}
local jsonStr = mw.text.jsonEncode(option)
-- 调用 ECharts 扩展
return frame:callParserFunction('#echarts', {
"option=" .. jsonStr,
"style=height:600px; min-width:920px; margin-top: 0px;"
})
end
return p
